-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
if GetLocale() ~= "deDE" then return end
local addon_name = ...
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.era.shaman.elemental.Name"] = "Elementar"
L["rm.era.shaman.elemental.Description"] = "Elementar ab Stufe 10 (die meisten Punkte in Elementar); zusammengestellt aus Icy Veins und Wowhead. Erdschock unterbricht und erledigt ein Ziel kurz vor dem Tod. In Bewegung: Flammenschock, sonst Frostschock. Solo mit dem Ziel im Nahkampf: Erdschock über 30 % Gesundheit, dann Nahkampf. Gegen drei oder mehr Gegner: Totem der Feuernova und Totem der glühenden Magma, wenn Sie im Nahkampf sind, und Kettenblitzschlag. Kettenblitzschlag während Elementarbeherrschung oder Freizaubern, sonst Blitzschlag. Erinnerungen: Blitzschlagschild, Waffe des Felsbeißers außerhalb von Schlachtzügen, Totem der Verbrennung oder der glühenden Magma, Totem der Manaquelle oder des heilenden Flusses, Elementarbeherrschung bei bereitem Kettenblitzschlag, Schnelligkeit der Natur und Welle der Heilung unter 30 %, Heilung nach einem Pull. Bannungen, Reinigen und Herabstufen von Rängen bleiben Ihnen überlassen."
L["rm.era.shaman.elemental.simulator.Name"] = "Elementar, Kettenblitzschlag bei Abklingzeit-Ende (Simulation)"
L["rm.era.shaman.elemental.simulator.Description"] = "Die Elementar-Liste von Simulation, eine Alternative zur empfohlenen integrierten Elementarrotation, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Kettenblitzschlag bei Abklingzeit-Ende, selbst gegen ein einzelnes Ziel, Erdschock, solange Elementarbeherrschung aktiv ist, sonst Blitzschlag. Schneller, aber viel manahungriger als die empfohlene integrierte Rotation; dieselbe Unterbrechung, dieselben Totems und Erinnerungen."
L["rm.era.shaman.enhancement.Name"] = "Verstärkung"
L["rm.era.shaman.enhancement.Description"] = "Stufen 1–60, auch auf Hardcore- und Self-Found-Realms, und jeder Schamane ohne Talentschwerpunkt; zusammengestellt aus Icy Veins, Wowhead und Simulation. Blitzschlag zieht aus der Distanz; Erdschock unterbricht. In Schlachtzügen nur Sturmschlag und Frostschock (Plätze für Schwächungszauber). Wenn drei oder mehr Gegner gegen Sie kämpfen, Totem der Feuernova und Totem der glühenden Magma. Dann Sturmschlag, Erdschock in den Schwächungszauber von Sturmschlag oder zum Erledigen, Flammenschock, wenn er voll durchlaufen kann, Erdschock, solange Sie die Hälfte Ihres Manas haben, und Blitzschlag, solange das Ziel außer Reichweite ist. Erinnerungen: Waffe des Felsbeißers solo und Waffe des Windzorns in Dungeons, Blitzschlagschild, Totem der Erdstärke, Totem der Verbrennung, Totem des Windzorns oder der luftgleichen Anmut, Totem der Manaquelle oder des heilenden Flusses, Heilung nach einem Pull und im Notfall. Totem der Steinklaue, Totem der Erdbindung, Totem-Twisting und Volksfähigkeiten sind als deaktivierte Schritte aufgeführt; Bannungen, Reinigen und Reinigungstotems bleiben Ihnen überlassen."
L["rm.era.shaman.enhancement.warcrafttavern.Name"] = "Verstärkung, Flammenschock zuerst (Warcraft Tavern)"
L["rm.era.shaman.enhancement.warcrafttavern.Description"] = "Verstärkung nach Warcraft Tavern, eine Alternative zur empfohlenen integrierten Verstärkungsrotation, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Waffe des Windzorns, sobald Sie sie erlernen, Sturmschlag, Flammenschock vor jedem direkten Schock, dann Erdschock, solange Ihre Bedrohung niedrig ist, oder in einer Gruppe Frostschock, sobald sie hoch ist; Totem der glühenden Magma und Kettenblitzschlag gegen Gruppen. Dieselben Totems und Erinnerungen wie die empfohlene integrierte Rotation."
L["rm.era.shaman.restoration.Name"] = "Wiederherstellung"
L["rm.era.shaman.restoration.Description"] = "Wiederherstellung ab Stufe 10 (die meisten Punkte in Wiederherstellung); zusammengestellt aus Icy Veins und Wowhead. Auf Ihr freundliches Ziel: Welle der Heilung während Schnelligkeit der Natur, Schnelligkeit der Natur unter 30 %, Geringe Welle der Heilung unter 40 %, Vergiftung heilen oder Krankheit heilen, Kettenheilung, wenn drei Gruppenmitglieder in Ihrer Nähe unter 85 % sind, sonst Welle der Heilung unter 90 %. Gegen einen Gegner, den sie bekämpft: Erdschock als Unterbrechung, Kettenblitzschlag gegen Gruppen, Flammenschock, Blitzschlag aus der Distanz, Nahkampf. Erinnerungen: Blitzschlagschild und Waffe des Felsbeißers solo, Totem der Manaflut in einer Gruppe, Totem der Manaquelle, Totem der Erdstärke, Totem der Verbrennung. Wen Sie heilen, Herabstufen von Rängen und Totem des Erdstoßes oder Reinigungstotems bleiben Ihnen überlassen; Pfad der Heilung auf dem Tank zu halten ist als deaktivierter Schritt aufgeführt."
L["rm.era.shaman.restoration.warcrafttavern.Name"] = "Wiederherstellung, Kettenheilung zuerst (Warcraft Tavern)"
L["rm.era.shaman.restoration.warcrafttavern.Description"] = "Wiederherstellung nach Warcraft Tavern, eine Alternative zur empfohlenen integrierten Wiederherstellungsrotation, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Kettenheilung ist die Heilung für jeden unter 90 %, mit Geringer Welle der Heilung für jemanden kurz vor dem Tod; Welle der Heilung ist nur für einen zugewiesenen Tankheiler mit Pfad der Heilung gedacht (als deaktivierter Schritt aufgeführt). Dieselben Reinigungen, derselbe Schaden gegen Gegner und dieselben Totem-Erinnerungen wie die empfohlene integrierte Rotation."
L["rm.forever.shaman.elemental.Name"] = "Elementar"
L["rm.forever.shaman.elemental.Description"] = "Elementar im Fernkampf, sobald Elementar Ihr Haupttalentbaum mit 21 Punkten ist (die Stufe von Lavaeruption), nach Icy Veins (davor spielt die integrierte Verstärkungsrotation den Nahkampf-Hybrid, den jeder Leitfaden empfiehlt). Zieht mit Blitzschlag (Kettenblitzschlag gegen eine Gruppe), wirkt in Bewegung nur Spontanzauber, nutzt Feuernova und Kettenblitzschlag gegen drei oder mehr Gegner, hält Flammenschock aufrecht, Lavaeruption bei Abklingzeit-Ende, Sturmschlag und Erdschock, wenn Sie Sturmschlag beherrschen, Feuernova bei Freizaubern in Gruppen, dann Blitzschlag. Erinnerungen: Schild, Waffenverzauberung, Totem der Verbrennung oder Totem der glühenden Magma, Gruppentotems, Elementarbeherrschung, Unterbrechung. Gesundheit und Mana sind für Addons unter Forever verborgen, daher entscheiden Sie selbst, wann Sie sich heilen und für Mana pausieren. Ihnen überlassen: Kiten mit Totem der Erdbindung, Frostschock, Reinigen und andere Totems."
L["rm.forever.shaman.enhancement.Name"] = "Verstärkung (Icy Veins)"
L["rm.forever.shaman.enhancement.Description"] = "Verstärkung im Nahkampf von Stufe 1 bis 60 und der Standard für jeden Schamanen vor Lavaeruption oder Totem der Manaflut. Zieht mit Blitzschlag aus der Distanz, dann Sturmschlag bei Abklingzeit-Ende, ein sofortiger Blitzschlag bei fünf Stapeln Waffe des Mahlstroms, Feuernova (mit einem gesetzten Feuertotem) und Flammenschock gegen drei oder mehr Gegner, Erdschock in den Schwächungszauber von Sturmschlag, Flammenschock in Gruppen und Erdschock bei Abklingzeit-Ende; Blitzschlag füllt die Lücke, solange das Ziel außer Reichweite ist. Gesundheit und Mana sind für Addons unter Forever verborgen, daher entscheiden Sie selbst, wann Sie sich heilen und für Mana pausieren (die integrierte Rotation nach Wowhead spart stattdessen Mana). Erinnerungen: Waffenverzauberung (Waffe des Windzorns, sonst Waffe der Flammenzunge, sonst Waffe des Felsbeißers), Wasser- oder Blitzschlagschild, Erdschock als Unterbrechung, Totem der Verbrennung oder Totem der glühenden Magma, Gruppentotems, Zorn des Scharfsehers, Totem der Steinklaue. Ihnen überlassen: Totem-Voreinstellungen, Frostschock, Reinigen und andere Totems."
L["rm.forever.shaman.enhancement.wowhead.Name"] = "Verstärkung, manasparend (Wowhead)"
L["rm.forever.shaman.enhancement.wowhead.Description"] = "Manasparende Verstärkung nach Wowhead und Mobalytics: Der automatische Angriff erledigt die Arbeit, Sturmschlag nur, solange die Manaregeneration von Verbesserter Sturmschlag nicht aktiv ist, kein Erdschock in der Rotation (Schocks zum Pullen und Unterbrechen), und in Gruppen oder gegen mehrere Gegner Totem der Verbrennung mit Feuernova bei Abklingzeit-Ende. Dieselben Erinnerungen an Waffenverzauberung, Schild und Unterbrechung wie die integrierte Rotation nach Icy Veins. Wählen Sie diese statt jener, wenn Ihnen das Mana ausgeht. Eine Alternative zur empfohlenen integrierten Verstärkungsrotation, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität."
L["rm.forever.shaman.restoration.Name"] = "Wiederherstellung"
L["rm.forever.shaman.restoration.Description"] = "Heilung, sobald Wiederherstellung Ihr Haupttalentbaum mit 16 Punkten ist (die Stufe von Totem der Manaflut), nach Icy Veins. Mit einem freundlichen Ziel: eine sofortige Welle der Heilung, sobald Sie Schnelligkeit der Natur nutzen, Vergiftung heilen und Krankheit heilen, Springflut auf ein Ziel ohne sie, Kettenheilung in einer Gruppe, Welle der Heilung. Wen Sie heilen, wählen Sie durch Anvisieren; Gesundheit und Mana sind für Addons unter Forever verborgen, daher entscheiden Sie selbst, wann Sie Schnelligkeit der Natur und Geringe Welle der Heilung einsetzen. Mit einem feindlichen Ziel und nichts zu heilen: Feuernova und Kettenblitzschlag gegen Gruppen, Sturmschlag und Erdschock, wenn Sie Sturmschlag beherrschen, Flammenschock auf Elitegegner und Bosse, Blitzschlag, dann Nahkampf. Erinnerungen: Wasserschild, Erdschock als Unterbrechung, Totem der Manaflut und Gruppen-Stärkungstotems. Ihnen überlassen: Herabstufen von Rängen, andere Totems, Reinigen und Geisterwolf."
L["rm.mop.shaman.elemental.Name"] = "Empfohlen"
L["rm.mop.shaman.elemental.Description"] = "Empfohlen für Elementar ab Stufe 10, gewählt in der Spezialisierung Elementar. Die Reihenfolge von Wowhead: ein Blitzschlag zum Eröffnen (Lavaeruption mit Entfesseltem Furor), Elemente entfesseln mit Entfesseltem Furor, Flammenschock, wenn er auf einem Ziel, das lange genug lebt, fehlt oder bald ausläuft, Lavaeruption auf Flammenschock (und bei jedem Lavasog), Elementarschlag, Erdschock bei sechs Aufladungen von Blitzschlagschild, solange Flammenschock noch 6 Sekunden hat, Kettenblitzschlag gegen zwei Gegner, Blitzschlag. Vier oder mehr Gegner gegen Sie: Totem des glühenden Magmas im Nahkampf, kostenlose Lavaeruptionen, Lavastrahl während Aszendenz, Kettenblitzschlag. In Bewegung zeigt sie nur Spontanzauber. Erinnerungen: Blitzschlagschild, Waffe der Flammenzunge, Totem der Verbrennung, Totem des Feuerelementars gegen Elitegegner und Bosse, Elementarbeherrschung, Aszendenz nach einer Lavaeruption, Schnelligkeit der Ahnen, Totem der Sturmpeitsche und Kampfrausch in einer Gruppe, Windstoß, Gewitter für Mana, Schamanistische Wut und Astralverschiebung bei niedriger Gesundheit. Erdbeben und Totem des Erdelementars sind aufgeführt, aber deaktiviert. Ihnen überlassen: Gunst des Geistwandlers, Flammenschock auf weiteren Zielen und wo Sie stehen."
L["rm.mop.shaman.enhancement.Name"] = "Empfohlen"
L["rm.mop.shaman.enhancement.Description"] = "Empfohlen für Verstärkung ab Stufe 10, gewählt in der Spezialisierung Verstärkung. Die Reihenfolge von Wowhead: Elemente entfesseln beim Heranlaufen, dann Elemente entfesseln mit Entfesseltem Furor, Elementarschlag und Blitzschlag bei fünf Stapeln von Waffe des Mahlstroms (oder bei drei eingewoben, wenn Ihr nächster Schlag mehr als eine Sekunde entfernt ist), Gewitterschlag während Aszendenz, Sturmschlag (Urtümlicher Schlag vor Stufe 26), Lavapeitsche, Flammenschock während Flammen entfesseln, Elemente entfesseln, Erdschock. Zwei oder mehr Gegner gegen Sie: Kettenblitzschlag statt Blitzschlag, Lavapeitsche zum Verteilen von Flammenschock, Feuernova ab vier, Totem des glühenden Magmas ab sechs. Erinnerungen: Blitzschlagschild, Waffe des Windzorns auf der Waffenhand und Waffe der Flammenzunge auf der Schildhand, Totem der Verbrennung, Totem des Feuerelementars, Wildgeist, Aszendenz nach Sturmschlag, Elementarbeherrschung, Schnelligkeit der Ahnen, Totem der Sturmpeitsche und Kampfrausch in einer Gruppe, Windstoß, Schamanistische Wut und Astralverschiebung bei niedriger Gesundheit. Totem des Erdelementars ist aufgeführt, aber deaktiviert."
L["rm.mop.shaman.enhancement.icyveins.Name"] = "Lavapeitsche zuerst (Icy Veins)"
L["rm.mop.shaman.enhancement.icyveins.Description"] = "Standardmäßig deaktiviert; dieselbe Umschaltung wie die empfohlene integrierte Verstärkungsrotation, aktivieren Sie sie also und deaktivieren Sie die andere, um sie zu verwenden. Die Reihenfolge von Icy Veins: Sturmschlag, dann Lavapeitsche, bevor Waffe des Mahlstroms ausgegeben wird, Blitzschlag bei fünf Stapeln oder ab drei, wenn er vor Ihrem nächsten Schlag landet, Elemente entfesseln, dann Flammenschock, Erdschock. Gegen vier oder mehr Gegner verteilt sie Flammenschock mit Lavapeitsche und nutzt Feuernova; gegen Gruppen ersetzt Kettenblitzschlag den Blitzschlag. Schamanistische Wut wird im Kampf bei Abklingzeit-Ende vorgeschlagen; übrige Erinnerungen wie bei der empfohlenen integrierten Rotation."
L["rm.mop.shaman.enhancement.simulator.Name"] = "Jeden Stapel einweben (Simulation)"
L["rm.mop.shaman.enhancement.simulator.Description"] = "Standardmäßig deaktiviert; dieselbe Umschaltung wie die empfohlene integrierte Verstärkungsrotation, aktivieren Sie sie also und deaktivieren Sie die andere, um sie zu verwenden. Die Liste des Simulators für Spieler, die Zauber zwischen Schlägen timen: Blitzschlag, Elementarschlag oder Kettenblitzschlag bei beliebig vielen Stapeln von Waffe des Mahlstroms, wann immer der Zauber vor Ihrem nächsten Schlag der Waffenhand fertig wird, Elemente entfesseln zusätzlich, wann immer Flammenschock fehlt, und Erdschock nur unter zwei Stapeln. Erinnerungen wie bei der empfohlenen integrierten Rotation."
L["rm.mop.shaman.restoration.Name"] = "Empfohlen"
L["rm.mop.shaman.restoration.Description"] = "Empfohlen für Wiederherstellung ab Stufe 10, gewählt in der Spezialisierung Wiederherstellung. Heilt Ihr freundliches Ziel (Rotation Master kann nicht wählen, wen Sie heilen): Große Welle der Heilung während Schnelligkeit der Ahnen, Heilende Woge unter 35 %, Geistreinigung bei Magie oder Flüchen, Elemente entfesseln, dann Heilender Regen, wenn drei Verbündete in der Nähe verletzt sind, Springflut, Kettenheilung bei Gruppenschaden, Große Welle der Heilung unter 60 %, Welle der Heilung unter 90 %. Mit einem angreifbaren Ziel verursacht sie stattdessen Schaden (Flammenschock, Lavaeruption, Elementarschlag, Blitzschlag). Erinnerungen: Wasserschild, Waffe der Lebensgeister, Erdschild auf Ihrem Fokus, Totem des heilenden Flusses, wenn jemand verletzt ist, Totem der Manaflut, Totem der Heilungsflut bei hohem Gruppenschaden, Elementarbeherrschung oder Führung der Ahnen, Schnelligkeit der Ahnen auf ein Ziel mit wenig Gesundheit, Gunst des Geistwandlers in Bewegung, Kampfrausch, Windstoß. Aszendenz und Totem der Geistverbindung sind aufgeführt, aber deaktiviert: Nutzen Sie sie, wenn Ihr Schlachtzug sie zuweist."
L["rm.mop.shaman.restoration.hekili.Name"] = "Gesundheitsleiter (Hekili)"
L["rm.mop.shaman.restoration.hekili.Description"] = "Standardmäßig deaktiviert; dieselbe Umschaltung wie die empfohlene integrierte Wiederherstellungsrotation, aktivieren Sie sie also und deaktivieren Sie die andere, um sie zu verwenden. Die Liste von Hekili hält Erdschild und Springflut auf Ihrem Ziel und Totem des heilenden Flusses und Heilender Regen am Laufen, wann immer sie fehlen, und heilt dann nach der durchschnittlichen Gesundheit Ihrer Gruppe im Umkreis von 40 Metern: Kettenheilung unter 80 %, Welle der Heilung auf ein Ziel unter 70 %, Große Welle der Heilung unter 60 %, Heilende Woge unter 40 %, mit Totem der Heilungsflut, Führung der Ahnen und Totem der Manaflut auf derselben Leiter. Ein angreifbares Ziel erhält Schaden plus Erdschock."
L["rm.mop.shaman.unspecialized.Name"] = "Ohne Spezialisierung"
L["rm.mop.shaman.unspecialized.Description"] = "Für Stufe 1 bis 9 und jeden Schamanen, der noch keine Spezialisierung gewählt hat; die integrierte Rotation jeder Spezialisierung übernimmt, sobald Sie eine wählen. Blitzschlag zum Ziehen aus der Distanz, Heilende Woge, wenn Sie wenig Gesundheit haben und allein sind, Urtümlicher Schlag, Erdschock und Blitzschlag außerhalb der Nahkampfreichweite. Hält Blitzschlagschild aufrecht."
L["rm.retail.shaman.elemental.Name"] = "Blizzard-Kampfassistent"
L["rm.retail.shaman.elemental.Description"] = "Empfohlen für Elementar in Midnight. Im Kampf verbirgt das Spiel nun Flammenschock, Ihre Stärkungszauber, Mahlstrom, Abklingzeiten und Gesundheit vor Addons, daher zeigt diese Rotation den eigenen Vorschlag von Blizzards Kampfassistent (die Ein-Tasten-Rotation) und pausiert, während Sie wirken oder kein Gegner anvisiert ist. Erinnerungen an das, was er auslässt: Aszendenz, Feuer- oder Sturmelementar und Schnelligkeit der Natur im Kampf, Gunst des Geistwandlers in Bewegung, Blitzschlagschild und Himmelszorn zwischen den Kämpfen (Blizzards Vorschlag hält Ihre Waffen- und Schildverzauberungen aufrecht), Windstoß bei einem unterbrechbaren Zauber (er leuchtet nur dort auf, wo das Spiel den Zauber auslesen lässt), Astralverschiebung, wann immer sie im Kampf bereit ist (die Gesundheit ist unter Retail verborgen, daher bleibt der Zeitpunkt Ihnen überlassen)."
L["rm.retail.shaman.elemental.icyveins.Name"] = "Referenz (Icy Veins)"
L["rm.retail.shaman.elemental.icyveins.Description"] = "Nur als Referenz, standardmäßig deaktiviert: die Reihenfolge von Icy Veins und SimulationCraft liest Flammenschock, Meister der Elemente und Sturmhüter, die Midnight im Kampf verbirgt; Mahlstrom ist unter Retail verborgen, daher werden die Verbraucher zu ihren Kosten eingesetzt statt bei fast vollem Mahlstrom. Sturmhüter und Lavaeruption vor dem Pull. Gegen drei oder mehr Gegner im Kampf: Sturmhüter, Schnelligkeit der Ahnen, Flammenschock, Kettenblitzschlag mit Sturmhüter, Elementarschlag, Erdbeben, Lavaeruption bei Lavasog, Sturmgewitter, Kettenblitzschlag. Sonst Sturmhüter, Schnelligkeit der Ahnen, Flammenschock und Voltaiklohe in ihren letzten 30 % außerhalb von Meister der Elemente, Lavaeruption, um es auszulösen, Sturmgewitter und Blitzschlag mit Sturmhüter währenddessen, Elementarschlag oder Erdschock währenddessen, Voltaiklohe, Sturmgewitter, Flammenschock oder Frostschock in Bewegung, Elementarschlag oder Erdschock, wann immer Sie es sich leisten können, Blitzschlag. Erinnerungen: Aszendenz, sobald Sturmhüter verbraucht ist, Elementare, Gunst des Geistwandlers und die gemeinsamen."
L["rm.retail.shaman.enhancement.Name"] = "Blizzard-Kampfassistent"
L["rm.retail.shaman.enhancement.Description"] = "Empfohlen für Verstärkung in Midnight. Zeigt den Vorschlag von Blizzards Kampfassistent (er verbraucht Waffe des Mahlstroms, hält Flammenschock aufrecht und übernimmt Wogendes Totem und Zerschlagung) und pausiert, während Sie wirken oder kein Gegner anvisiert ist. Erinnerungen an das, was er auslässt: Aszendenz, Schicksalswinde und Wildgeist im Kampf, Blitzschlagschild und Himmelszorn zwischen den Kämpfen (Blizzards Vorschlag hält Waffe des Windzorns aufrecht), Windstoß, Astralverschiebung."
L["rm.retail.shaman.enhancement.stormbringer.Name"] = "Sturmbringer-Referenz (SimulationCraft)"
L["rm.retail.shaman.enhancement.stormbringer.Description"] = "Nur als Referenz, standardmäßig deaktiviert: die Sturmbringer-Liste von SimulationCraft (Icy Veins und Wowhead stimmen überein) liest Flammenschock, Tobende Blitze, Peitschende Flammen und Abklingzeit-Timer, die Midnight im Kampf verbirgt. Gegen drei oder mehr Gegner im Kampf: Tobende Blitze für den Stärkungszauber, Sturmgewitter bei 10 Stapeln Waffe des Mahlstroms, Kettenblitzschlag bei 9, Tobende Blitze, Lavapeitsche, Zerschlagung. Dann Urzeitlicher Sturm bei 9, Voltaiklohe oder Flammenschock, wenn Flammenschock fehlt, Zerschlagung, Tobende Blitze für den Stärkungszauber, Lavapeitsche für Peitschende Flammen, Windschlag, Sturmgewitter oder Blitzschlag bei 10 (8, wenn Voltaiklohe oder Tobende Blitze fast bereit sind), Sturmschlag bei zwei Aufladungen, Lavapeitsche, Sturmschlag, Voltaiklohe, Tobende Blitze, Blitzschlag bei 5, Flammenschock. Erinnerungen: Schicksalswinde, Aszendenz außerhalb von Schicksalswinden, Wildgeist und die gemeinsamen."
L["rm.retail.shaman.enhancement.totemic.Name"] = "Totemiker-Referenz (SimulationCraft)"
L["rm.retail.shaman.enhancement.totemic.Description"] = "Nur als Referenz, standardmäßig deaktiviert: die Totemiker-Liste von SimulationCraft liest Flammenschock, Heiße Hand, Wirbelndes Feuer, Tobende Blitze und Schicksalswinde, die Midnight im Kampf verbirgt. Gegen drei oder mehr Gegner im Kampf: Tobende Blitze, Kettenblitzschlag bei 5 Stapeln Waffe des Mahlstroms. Dann Voltaiklohe oder Flammenschock, wenn Flammenschock fehlt, Wogendes Totem, Zerschlagung, Lavapeitsche mit Heißer Hand oder Wirbelndem Feuer, Tobende Blitze für den Stärkungszauber, Urzeitlicher Sturm bei 10, Windschlag, Tobende Blitze und Sturmschlag während Schicksalswinden, Blitzschlag bei 5, Tobende Blitze, Lavapeitsche, Sturmschlag, Voltaiklohe, Flammenschock. Dieselben Erinnerungen wie die Sturmbringer-Referenz."
L["rm.retail.shaman.initial.Name"] = "Blizzard-Kampfassistent"
L["rm.retail.shaman.initial.Description"] = "Empfohlen, bevor Sie eine Spezialisierung wählen (solange das Spiel die Anfangsspezialisierung des Schamanen meldet). Hebt den Zauber hervor, den Blizzards Kampfassistent als Nächstes vorschlägt, den einzigen Rotationshinweis, den das Spiel ein Addon im Kampf in Midnight noch auslesen lässt; sie wartet, während Sie wirken oder kanalisieren. Daneben die Erinnerungen, die jede integrierte Schamane-Rotation teilt, jeweils sobald Sie den Zauber kennen. Wenn Sie auf Stufe 10 eine Spezialisierung wählen, übernehmen die integrierten Rotationen dieser Spezialisierung."
L["rm.retail.shaman.restoration.Name"] = "Icy Veins"
L["rm.retail.shaman.restoration.Description"] = "Wiederherstellung in Midnight, als Referenz: Blizzards Kampfassistent deckt keine Heiler ab, das Spiel verbirgt im Kampf die Gesundheit aller, und Rotation Master wählt einen Zauber, kein Ziel, daher ordnet diese Rotation Ihre Heilwerkzeuge auf jedem Ziel, das Sie anvisieren, nach Bereitschaft und überlässt Ihnen die Entscheidung, wen Sie heilen. Bei einem freundlichen Ziel: Totem des heilenden Flusses, Leben entfesseln, Heilender Regen in einer Gruppe, Wogendes Totem, Springflut, Kettenheilung in einer Gruppe, Welle der Heilung. Bei einem Gegner: Flammenschock, wenn er fehlt, Lavaeruption, Blitzschlag. Erinnerungen: Wasserschild, Erdschild auf einem freundlichen Ziel und Himmelszorn zwischen den Kämpfen; Schnelligkeit der Natur im Kampf; Totem der Heilungsflut und Totem der Geistverbindung im Gruppenkampf; Windstoß; Astralverschiebung."
L["rm.sod.shaman.elemental.Name"] = "Elementar (SoD)"
L["rm.sod.shaman.elemental.Description"] = "Elementar in der Saison der Entdeckungen ab Stufe 10 (die meisten Punkte in Elementar); zusammengestellt aus Simulation Phase 6, Wowhead und Icy Veins. Erdschock unterbricht. In Bewegung: Flammenschock, Erdschock bei acht Aufladungen von Blitzschlagschild, Lavaeruption oder Kettenblitzschlag bei einem Proc von Kraftwoge. Gegen drei oder mehr Gegner: Flammenschock, Kettenblitzschlag, Feuernova, Lavaeruption, Erdschock bei acht Aufladungen, Totem der glühenden Magma. Dann Lavaeruption bei Kraftwoge, Flammenschock aufrechterhalten, Lavaeruption, solange Ihr Flammenschock anhält, Erdschock bei acht Aufladungen, Kettenblitzschlag gegen zwei Gegner, Blitzschlag. Erinnerungen: Waffe der Flammenzunge für Brennen, Blitzschlagschild, Erdschild auf Ihnen selbst, Geist des Alphas, Wildgeist, Schamanistische Wut, Elementarbeherrschung, Totems. Schmuckstücke, Totemische Projektion, Bannungen und Reinigen bleiben Ihnen überlassen."
L["rm.sod.shaman.enhancement.Name"] = "Verstärkung (SoD)"
L["rm.sod.shaman.enhancement.Description"] = "Saison der Entdeckungen, Stufen 1–60 mit Runen, sobald Sie sie gravieren, Beidhändigkeit oder Zweihandwaffe, und jeder Schamane der Saison der Entdeckungen, zu dem keine andere integrierte Rotation passt; zusammengestellt aus Simulation Phase 6, Icy Veins und Wowhead. Flammenschock zieht; Erdschock unterbricht. Gegen drei oder mehr Gegner: Totem der glühenden Magma, Feuernova von einem Feuertotem, Kettenblitzschlag bei vier Stapeln von Waffe des Mahlstroms, Flammenschock. Dann Lavaeruption bei fünf Stapeln von Waffe des Mahlstroms, Sturmschlag, Lavapeitsche, Blitzschlag bei fünf Stapeln, Flammenschock, wenn er durchlaufen kann, Erdschock, Schmelzschlag, Blitzschlag aus der Distanz. Erinnerungen: Waffe des Windzorns (davor Waffe des Felsbeißers), Waffe der Flammenzunge auf einer Schildhandwaffe mit Lavapeitsche (sonst Windzorn; nie auf einem Schild; eine Zeile von Icy Veins mit Windzorn auf beiden Waffen ist als deaktivierter Schritt aufgeführt), Wasser- oder Blitzschlagschild, Geist des Alphas, Wildgeist, Schamanistische Wut unter 65 % Mana, Totems, Führung der Ahnen. Totemische Projektion, Bannungen und Reinigen bleiben Ihnen überlassen."
L["rm.sod.shaman.restoration.Name"] = "Wiederherstellung (SoD)"
L["rm.sod.shaman.restoration.Description"] = "Wiederherstellung in der Saison der Entdeckungen ab Stufe 10 (die meisten Punkte in Wiederherstellung); zusammengestellt aus Icy Veins und Wowhead. Auf Ihr freundliches Ziel: Springflut, dann Geringe Welle der Heilung unter 40 %, Vergiftung heilen oder Krankheit heilen, Heilender Regen, wenn drei Gruppenmitglieder in Ihrer Nähe unter 85 % sind, Kettenheilung, wenn es zwei sind (sofort bei einem Proc von Kraftwoge), Springflut unter 95 % für Flutwellen, Welle der Heilung unter 90 %. Gegen einen Gegner kämpft sie. Erinnerungen: Wasserschild (davor Blitzschlagschild), Erdschild auf Ihrem freundlichen Ziel oder Ihnen selbst, Schamanistische Wut, Totem der Manaflut, Totem der Manaquelle und Totem der Erdstärke. Wen Sie heilen und Totem des Erdstoßes oder Reinigungstotems bleiben Ihnen überlassen."
L["rm.sod.shaman.tank.Name"] = "Tank, Weg der Erde (SoD)"
L["rm.sod.shaman.tank.Description"] = "Tank in der Saison der Entdeckungen, gewählt, sobald Weg der Erde graviert ist; zusammengestellt aus Icy Veins, Wowhead, Simulation und Warcraft Tavern. Flammenschock zieht. Erdschock spottet ein Ziel im Nahkampf, das Sie nicht angreift, und unterbricht. Gegen zwei oder mehr Gegner: Schmelzschlag, Flammenschock, Kettenblitzschlag bei fünf Stapeln von Waffe des Mahlstroms oder bei Kraftwoge, Feuernova bei fünf Stapeln. Dann Flammenschock aufrechterhalten, Lavaeruption bei Kraftwoge oder solange Flammenschock anhält, Sturmschlag, Erdschock, Blitzschlag bei fünf Stapeln, Schmelzschlag, Frostschock. Erinnerungen: Waffe des Felsbeißers, Blitzschlagschild, Geist des Alphas auf Ihnen selbst, Wildgeist, Schamanistische Wut, Totem der Verbrennung oder der glühenden Magma und Gruppentotems."
L["rm.tbc.shaman.elemental.icyveins.Name"] = "Elementar (Icy Veins & Simulation)"
L["rm.tbc.shaman.elemental.icyveins.Description"] = "Elementar-Zauberwirker für den Talentbaum Elementar. Blitzschlag ist der Füller; Kettenblitzschlag kommt mit Elementarbeherrschung, bei Freizaubern, solange Sie 40 % Mana haben, oder beliebig über 80 %; Flammenschock nur in Bewegung; Erdschock unterbricht; Feuernova, Kettenblitzschlag und Totem des glühenden Magmas für Gruppen von Gegnern. Vor Kettenblitzschlag wird ein Ziel im Nahkampf dem automatischen Angriff überlassen, um Mana zu sparen. Erinnerungen: Wasser- oder Blitzschlagschild, eine Waffenverzauberung, Totem des Ingrimms (oder Totem der Verbrennung bei langen Kämpfen), Totem des stürmischen Zorns, Totem der Manaquelle, Ruf der Totems nach dem Kampf, Elementarbeherrschung und Kampfrausch/Heldentum."
L["rm.tbc.shaman.elemental.nextaction.Name"] = "Elementar (NextActionTBC)"
L["rm.tbc.shaman.elemental.nextaction.Description"] = "Elementar nach NextActionTBC, eine Alternative zur empfohlenen integrierten Elementarrotation nach Icy Veins, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Hält Flammenschock auf dem Ziel, Kettenblitzschlag nur gegen zwei oder mehr Gegner bei über 30 % Mana, sonst Blitzschlag. Erinnert an Blitzschlagschild, eine Waffenverzauberung, Elementarbeherrschung und Kampfrausch/Heldentum; Totems bleiben manuell."
L["rm.tbc.shaman.elemental.wowhead.Name"] = "Elementar (Wowhead)"
L["rm.tbc.shaman.elemental.wowhead.Description"] = "Elementar nach Wowhead, eine Alternative zur empfohlenen integrierten Elementarrotation nach Icy Veins, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Auf Stufe 70 Kettenblitzschlag bei Abklingzeit-Ende mit Blitzschlägen dazwischen (beim Leveln nur mit Elementarbeherrschung oder Freizaubern), Flammenschock nur in Bewegung, Erdschock, um ein Ziel zu erledigen, das stürbe, bevor ein Zauber ankommt. Dieselben Erinnerungen an Totems, Schild und Abklingzeiten wie die Icy-Veins-Variante."
L["rm.tbc.shaman.enhancement.icyveins.Name"] = "Verstärkung (Icy Veins)"
L["rm.tbc.shaman.enhancement.icyveins.Description"] = "Verstärkung im Nahkampf von Stufe 1 bis 70 und der Standard für jeden Schamanen, zu dem keine andere integrierte Rotation passt. Zieht mit Blitzschlag aus der Distanz, unterbricht mit Erdschock, setzt bei drei oder mehr nahen Gegnern Totem der Feuernova und Totem des glühenden Magmas, dann Sturmschlag, Erdschock, solange der Schwächungszauber von Sturmschlag aktiv ist, Flammenschock auf ein Ziel, das lange genug lebt, Erdschock bei Abklingzeit-Ende und Blitzschlag, solange das Ziel außer Reichweite ist. Eigene Erinnerungen: Waffenverzauberungen, Wasser- oder Blitzschlagschild, Totem der Erdstärke, Totem des Windzorns (Gruppe) oder Totem der luftgleichen Anmut (solo), Totem der Verbrennung bei langen Kämpfen, Wassertotems, Schamanistische Wut, Kampfrausch/Heldentum bei Bossen, Totem der Steinklaue und Totem des Erdelementars beim Solospiel. Totem des Feuerelementars ist ein optionaler Schritt, der deaktiviert beginnt. Totemplatzierung, Geisterwolf und Heilung bleiben Ihnen überlassen."
L["rm.tbc.shaman.enhancement.simulator.Name"] = "Verstärkung (Wowhead & Simulation)"
L["rm.tbc.shaman.enhancement.simulator.Description"] = "Das Schlachtzugsmodell für Stufe 70 zum Totem-Twisting, eine Alternative zur empfohlenen integrierten Verstärkungsrotation nach Icy Veins, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Sturmschlag, eingewobenes Totem der Feuernova, Flammenschock, sobald er ausgelaufen ist, und Erdschock als Hauptschock, Blitzschlag nur außer Reichweite. Die Erinnerungen wechseln (Twisting) zwischen Totem des Windzorns und Totem der luftgleichen Anmut, halten das Totem der Verbrennung aufrecht, nutzen Schamanistische Wut bei knappem Mana und teilen die Pflege von Waffenverzauberung, Schild und Totems mit der Icy-Veins-Variante."
L["rm.tbc.shaman.restoration.Name"] = "Wiederherstellung"
L["rm.tbc.shaman.restoration.Description"] = "Heilung für den Talentbaum Wiederherstellung, auf Ihr freundliches Ziel (oder Sie selbst ohne Ziel): Schnelligkeit der Natur und Welle der Heilung oder Geringe Welle der Heilung im Notfall, Vergiftung heilen und Krankheit heilen, Erdschild auf Ihrem Fokus, Kettenheilung, wenn drei nahe Verbündete verletzt sind, sonst Welle der Heilung. Mit einem feindlichen Ziel wechselt sie für das Solospiel zu Flammenschock und Blitzschlag. Erinnerungen: Wasserschild, Erdschild auf Ihrem Fokus (legen Sie den Tank als Fokus fest), Totem der Manaflut, Totem der Manaquelle und Totem der Erdstärke in einer Gruppe, Kampfrausch/Heldentum. Wen Sie heilen und mit welchem Rang, bleibt Ihnen überlassen."
